        assert nazwiska_z_plikow(["kw 2.pdf", "Sobczak Tomasz - Pawlak Grzegorz - sprzedaż RI - Zalesie.pdf"]) == ["Sobczak", "Pawlak"]

    def test_brak_konwencji(self):
