        pola = [{"nazwa": "aaa: zbywca", "wartosc": "Jan Kowalski"},
                {"nazwa": "STALE: nazwiska stron czynnosci", "wartosc": "Sobczak - Pawlak"}]
        assert nazwa_sprawy(pola) == "Sobczak – Pawlak"

